public final class AppRegistry implements Registry {
    private static final class FxRates_Holder {
        static final FxRates INSTANCE = new FxRates();
    }

    private static final class FeeCalculator_Holder {
        static final FeeCalculator INSTANCE = new FeeCalculator(FxRates_Holder.INSTANCE);
    }

    private static PaymentAttempt new_PaymentAttempt() {        // a prototype
        return new PaymentAttempt(FeeCalculator_Holder.INSTANCE);
    }

    @Override
    public <T> T get(Class<T> type) {
        if (type == FxRates.class) return type.cast(FxRates_Holder.INSTANCE);
        if (type == FeeCalculator.class) return type.cast(FeeCalculator_Holder.INSTANCE);
        if (type == PaymentAttempt.class) return type.cast(new_PaymentAttempt());
        throw new ContainerException("No component provides " + type.getSimpleName());
    }
}

