object AppRegistry {
    private object FxRatesHolder { val INSTANCE = FxRates() }
    private object FeeCalculatorHolder { val INSTANCE = FeeCalculator(FxRatesHolder.INSTANCE) }

    private fun newPaymentAttempt() = PaymentAttempt(FeeCalculatorHolder.INSTANCE)   // a prototype

    @Suppress("UNCHECKED_CAST")
    fun <T> get(type: Class<T>): T = when (type) {
        FxRates::class.java -> FxRatesHolder.INSTANCE
        FeeCalculator::class.java -> FeeCalculatorHolder.INSTANCE
        PaymentAttempt::class.java -> newPaymentAttempt()
        else -> throw ContainerException("No component provides ${type.simpleName}")
    } as T
}

