        if (type == FxRates.class) return type.cast(FxRatesHolder.INSTANCE);
        if (type == FeeCalculator.class) return type.cast(FeeCalculatorHolder.INSTANCE);
        if (type == Quote.class) return type.cast(newQuote());
        throw new IllegalArgumentException("No component provides " + type.getSimpleName());
    }
